const m = location.pathname.match(/^(.*?\/jwglxt)\//); const base = (m ? m[1] : '') + '/';
let jcd = 0; for (let p = __p.startPeriod; p <= __p.endPeriod; p++) jcd += Math.pow(2, p - 1);
const zcd = String(Math.pow(2, __p.week - 1));
const PAGE = 1000; let items = []; let page = 1;
while (true) {
  const body = new URLSearchParams({ fwzt: 'cx', xqh_id: '', xnm: String(__p.xnm), xqm: String(__p.xqm), cdlb_id: '', cdejlb_id: '', qszws: '', jszws: '', cdmc: __p.keyword || '', lh: '', jyfs: '0', cdjylx: '', zcd: zcd, xqj: String(__p.weekday), jcd: String(jcd), _search: 'false', nd: String(Date.now()), 'queryModel.showCount': String(PAGE), 'queryModel.currentPage': String(page), 'queryModel.sortName': 'cdbh', 'queryModel.sortOrder': 'asc', time: '1' });
  const resp = await fetch(base + 'cdjy/cdjy_cxKxcdlb.html?doType=query&gnmkdm=N2155', { method: 'POST', body: body, credentials: 'include', headers: { 'X-Requested-With': 'XMLHttpRequest' } });
  if (!resp.ok) throw '接口返回 ' + resp.status + '，请确认已登录教务系统（部分学校需先打开一次“空闲教室查询”菜单）';
  const text = await resp.text(); let json; try { json = JSON.parse(text); } catch (e) { throw '返回的不是 JSON（可能未登录或会话过期）'; }
  const got = json.items || []; items = items.concat(got);
  const totalPage = Number(json.totalPage || 0);
  if (got.length < PAGE || (totalPage && page >= totalPage) || page >= 50) break;
  page++;
}
return { rooms: items.map(function (i) { return { name: i.cdmc || '', building: i.jxlmc || i.lh || '', campus: i.xqmc || '', type: i.cdlbmc || '', seats: i.zws || '' }; }) };
